        private static readonly CultureInfo Inv = CultureInfo.InvariantCulture;
        public static Dictionary<string,object> D(params object[] pairs) { Dictionary<string,object> d=new Dictionary<string,object>(); for(int i=0;i<pairs.Length;i+=2)d.Add((string)pairs[i],pairs[i+1]);return d; }
        internal static void ValidateOutput(object value)
        {
            if(value is double&&!QuantumMath.IsFinite((double)value))throw new ArgumentException("Numerical result exceeds the finite FP64 range.");
            Dictionary<string,object> map=value as Dictionary<string,object>;if(map!=null){foreach(object item in map.Values)ValidateOutput(item);return;}
            IEnumerable sequence=value as IEnumerable;if(sequence!=null&&!(value is string))foreach(object item in sequence)ValidateOutput(item);
        }
        public static Dictionary<string,object>[] Capabilities
        {
            get {
                List<Dictionary<string,object>> r=new List<Dictionary<string,object>>();
                AddCapabilities(r,"q.math","normalize norm probabilities bloch from-bloch validate-bloch density validate-density purity entropy overlap fidelity trace-distance gate-matrix compare-gates unitary tensor commutator eigen expectation canonical-phase","bounded-complex-FP64","numerical");
                AddCapabilities(r,"q.query","amplitudes probabilities marginal reduced-density purity entropy expectation concurrence negativity stabilizers fidelity","selected-coherent-register","analysis");
                AddCapabilities(r,"q.resource","memory max-n factor-memory tranche-plan sampling shots grover qec headroom auto","classical-resource-formulas","resource-estimate");
                AddCapabilities(r,"q.model","spectrum ising qubo-to-ising evolve mbqc","bounded-complex-FP64","numerical");
                AddCapabilities(r,"q.model","compare compare-codes topology","documented-theory","theory");
                AddCapabilities(r,"q.lesson","amplitude-vs-probability entanglement complexity parallelism stabilizer magic algorithms pqc","documented-theory","theory");
                return r.ToArray();
            }
        }
        private static void AddCapabilities(List<Dictionary<string,object>> list,string ns,string actions,string backend,string kind) {foreach(string a in actions.Split(' '))list.Add(D("command",ns+" "+a,"namespace",ns,"action",a,"installed",true,"backend",backend,"resultKind",kind,"limits",ns=="q.query"?"Prefix <=4096; full joint analysis <=16 qubits/65536 states; one-qubit reductions via exact native spin <=29.":"Vectors <=4096, matrices <=16x16; resource counts are estimates, not allocations.","validation","calculator-validation.json"));}
        public static bool Supports(string ns,string action){foreach(Dictionary<string,object> d in Capabilities)if((string)d["command"]==ns.ToLowerInvariant()+" "+action.ToLowerInvariant())return true;return false;}

        // Reconstruct split terminal words, then parse quoted/bracketed fields.
        // A field value is data: it is never evaluated as host or shell code.
        public static Dictionary<string,string> ParseFields(string[] words)
        {
            if(words==null||words.Length<2)throw new ArgumentException("Use namespace action key=value.");
            string text=String.Join(" ",words,2,words.Length-2);if(text.Length>16384)throw new ArgumentException("Calculator input exceeds 16 KiB.");
            Dictionary<string,string> result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);int p=0;
            while(p<text.Length){while(p<text.Length&&Char.IsWhiteSpace(text[p]))p++;if(p==text.Length)break;int start=p;while(p<text.Length&&(Char.IsLetterOrDigit(text[p])||text[p]=='-'||text[p]=='_'))p++;if(p==start||p>=text.Length||text[p]!='=')throw new ArgumentException("Expected key=value near "+text.Substring(start,Math.Min(32,text.Length-start))+".");string key=text.Substring(start,p-start);p++;start=p;int depth=0;char quote='\0';bool escaped=false;
                while(p<text.Length){char c=text[p];if(quote!='\0'){if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c==quote)quote='\0';p++;continue;}if(c=='\"'||c=='\''){quote=c;p++;continue;}if(c=='['||c=='('){if(++depth>32)throw new ArgumentException("Field nesting exceeds 32.");}else if(c==']'||c==')'){if(--depth<0)throw new ArgumentException("Unbalanced field brackets.");}else if(Char.IsWhiteSpace(c)&&depth==0)break;p++;}
                if(quote!='\0'||depth!=0)throw new ArgumentException("Unclosed quoted/bracketed field.");string value=text.Substring(start,p-start);if(value.Length==0||result.ContainsKey(key))throw new ArgumentException("Empty or duplicate field "+key+".");result.Add(key,Unquote(value));}
            return result;
        }
        public static string Unquote(string s){s=s.Trim();if(s.Length>=2&&((s[0]=='\"'&&s[s.Length-1]=='\"')||(s[0]=='\''&&s[s.Length-1]=='\''))){s=s.Substring(1,s.Length-2);StringBuilder b=new StringBuilder();for(int i=0;i<s.Length;i++){if(s[i]=='\\'){if(++i>=s.Length||(s[i]!='\\'&&s[i]!='\"'&&s[i]!='\''))throw new ArgumentException("Only quote and backslash escapes are accepted.");}b.Append(s[i]);}return b.ToString();}return s;}
        public static string[] SplitList(string s){s=s.Trim();if(s.Length<2||s[0]!='['||s[s.Length-1]!=']')throw new ArgumentException("Expected bracket list.");s=s.Substring(1,s.Length-2);List<string> r=new List<string>();int begin=0,depth=0;char quote='\0';bool escaped=false;for(int p=0;p<s.Length;p++){char c=s[p];if(quote!='\0'){if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c==quote)quote='\0';continue;}if(c=='\"'||c=='\''){quote=c;continue;}if(c=='['||c=='(')depth++;else if(c==']'||c==')'){if(--depth<0)throw new ArgumentException("List brackets are unbalanced.");}else if(c==','&&depth==0){r.Add(s.Substring(begin,p-begin).Trim());begin=p+1;}}if(depth!=0||quote!='\0')throw new ArgumentException("List is unclosed.");if(s.Trim().Length>0)r.Add(s.Substring(begin).Trim());foreach(string v in r)if(v.Length==0)throw new ArgumentException("List contains an empty item.");return r.ToArray();}
        private static string Required(Dictionary<string,string> f,string key){string s;if(!f.TryGetValue(key,out s))throw new ArgumentException("Missing field "+key+".");return s;}
        private static string Optional(Dictionary<string,string> f,string key,string fallback){string s;return f.TryGetValue(key,out s)?s:fallback;}
        public static void CheckFields(Dictionary<string,string> f,string allowed){HashSet<string> names=new HashSet<string>(allowed.Split(' '),StringComparer.OrdinalIgnoreCase);foreach(string k in f.Keys)if(!names.Contains(k))throw new ArgumentException("Unknown field "+k+".");}
        private static void Choice(Dictionary<string,string> f,string key,string expected){if(f.ContainsKey(key)&&!String.Equals(f[key],expected,StringComparison.OrdinalIgnoreCase))throw new ArgumentException(key+" must be "+expected+".");}
        public static double Real(string s){Complex c=ComplexExpression(s);if(Math.Abs(c.Imaginary)>1e-12)throw new ArgumentException("Expected a real value.");return c.Real;}
        public static int Integer(string s,int min,int max){double x;try{x=Real(s);}catch(ArgumentException){throw new ArgumentException("Expected an integer value.");}if(x!=Math.Floor(x))throw new ArgumentException("Expected an integer value.");if(x<min||x>max)throw new ArgumentOutOfRangeException("number","Integer must be in "+min+".."+max+".");return (int)x;}
        private static BigInteger Big(string s,bool positive){BigInteger n;if(s.Length>320||!BigInteger.TryParse(s,NumberStyles.Integer,Inv,out n)||n<0||(positive&&n==0))throw new ArgumentException("Expected a nonnegative decimal integer"+(positive?" greater than zero":"")+".");return n;}
        public static Complex[] ParseComplexVector(string s){string[] a=SplitList(s);if(a.Length<1||a.Length>4096)throw new ArgumentException("Vector length must be 1..4096.");Complex[] v=new Complex[a.Length];for(int i=0;i<a.Length;i++)v[i]=ComplexExpression(a[i]);return v;}
        public static Complex[,] ParseComplexMatrix(string s){s=s.Trim();if(s.Length>0&&s[0]!='['){if(s.Equals("I2",StringComparison.OrdinalIgnoreCase))return Identity(2);return GateMatrix(s.ToLowerInvariant(),new double[0]);}string[] rows=SplitList(s);if(rows.Length<1||rows.Length>16)throw new ArgumentException("Matrix supports 1..16 rows.");Complex[][] a=new Complex[rows.Length][];int cols=0;for(int i=0;i<a.Length;i++){a[i]=ParseComplexVector(rows[i]);if(i==0)cols=a[i].Length;if(a[i].Length!=cols||cols>16)throw new ArgumentException("Matrix must be rectangular, <=16 columns.");}Complex[,] m=new Complex[a.Length,cols];for(int i=0;i<a.Length;i++)for(int j=0;j<cols;j++)m[i,j]=a[i][j];return m;}
        public static Complex ComplexExpression(string expression){return new ComplexParser(expression).Evaluate();}
        private sealed class ComplexParser
        {
            private readonly string text;private int p,depth,ops;
            public ComplexParser(string s){text=s??"";if(text.Length==0||text.Length>2048)throw new ArgumentException("Expression length must be 1..2048.");}
            private void Space(){while(p<text.Length&&Char.IsWhiteSpace(text[p]))p++;}
            private bool Eat(char c){Space();if(p<text.Length&&text[p]==c){p++;return true;}return false;}
            private Complex Checked(Complex c){if(++ops>1024||Double.IsNaN(c.Real)||Double.IsInfinity(c.Real)||Double.IsNaN(c.Imaginary)||Double.IsInfinity(c.Imaginary))throw new ArgumentException("Expression is nonfinite or exceeds operation bound.");return new Complex(c.Real==0?0:c.Real,c.Imaginary==0?0:c.Imaginary);}
            public Complex Evaluate(){Complex c=Add();Space();if(p!=text.Length)throw new ArgumentException("Unexpected expression token near "+text.Substring(p,Math.Min(24,text.Length-p))+".");return Checked(c);}
            private Complex Add(){Complex c=Mul();while(true){if(Eat('+'))c=Checked(c+Mul());else if(Eat('-'))c=Checked(c-Mul());else return c;}}
            private Complex Mul(){Complex c=Unary();while(true){if(Eat('*'))c=Checked(c*Unary());else if(Eat('/')){Complex d=Unary();if(d==Complex.Zero)throw new ArgumentException("Division by zero.");c=Checked(c/d);}else return c;}}
            private Complex Unary(){if(++depth>32)throw new ArgumentException("Expression depth exceeds 32.");try{if(Eat('+'))return Unary();if(Eat('-'))return Checked(-Unary());return Power();}finally{depth--;}}
            private Complex Power(){Complex c=Atom();if(Eat('^'))c=Checked(Complex.Pow(c,Unary()));return c;}
            private Complex Atom(){Space();if(Eat('(')){Complex c=Add();if(!Eat(')'))throw new ArgumentException("Missing closing parenthesis.");return c;}Space();int begin=p;if(p<text.Length&&(Char.IsDigit(text[p])||text[p]=='.')){while(p<text.Length&&(Char.IsDigit(text[p])||text[p]=='.'))p++;if(p<text.Length&&(text[p]=='e'||text[p]=='E')){p++;if(p<text.Length&&(text[p]=='+'||text[p]=='-'))p++;while(p<text.Length&&Char.IsDigit(text[p]))p++;}double d;if(!Double.TryParse(text.Substring(begin,p-begin),NumberStyles.Float,Inv,out d))throw new ArgumentException("Invalid numeric literal.");return Checked(new Complex(d,0));}while(p<text.Length&&Char.IsLetter(text[p]))p++;if(p==begin)throw new ArgumentException("Expected a number, constant, or function.");string n=text.Substring(begin,p-begin).ToLowerInvariant();if(n=="pi")return new Complex(Math.PI,0);if(n=="e")return new Complex(Math.E,0);if(n=="i")return Complex.ImaginaryOne;if(!Eat('('))throw new ArgumentException("Unknown constant "+n+".");Complex x=Add();if(!Eat(')'))throw new ArgumentException("Missing function closing parenthesis.");switch(n){case "sqrt":return Checked(Complex.Sqrt(x));case "sin":return Checked(Complex.Sin(x));case "cos":return Checked(Complex.Cos(x));case "tan":return Checked(Complex.Tan(x));case "exp":return Checked(Complex.Exp(x));case "log":return Checked(Complex.Log(x));case "abs":return new Complex(Complex.Abs(x),0);case "asin":return Checked(Complex.Asin(x));case "acos":return Checked(Complex.Acos(x));case "atan":return Checked(Complex.Atan(x));default:throw new ArgumentException("Unknown function "+n+".");}}
        }
        public static object[] ComplexJson(Complex c){return new object[]{c.Real,c.Imaginary};}
        public static object[] VectorJson(Complex[] v){object[] a=new object[v.Length];for(int i=0;i<v.Length;i++)a[i]=ComplexJson(v[i]);return a;}
        public static object[] MatrixJson(Complex[,] m){object[] a=new object[m.GetLength(0)];for(int i=0;i<a.Length;i++){object[] row=new object[m.GetLength(1)];for(int j=0;j<row.Length;j++)row[j]=ComplexJson(m[i,j]);a[i]=row;}return a;}
        public static Complex[,] Identity(int n){Complex[,] m=new Complex[n,n];for(int i=0;i<n;i++)m[i,i]=Complex.One;return m;}
        public static Complex[,] Dagger(Complex[,] a){Complex[,] b=new Complex[a.GetLength(1),a.GetLength(0)];for(int i=0;i<a.GetLength(0);i++)for(int j=0;j<a.GetLength(1);j++)b[j,i]=Complex.Conjugate(a[i,j]);return b;}
        public static Complex[,] MatrixMultiply(Complex[,] a,Complex[,] b){if(a.GetLength(1)!=b.GetLength(0))throw new ArgumentException("Matrix dimensions do not match.");Complex[,] c=new Complex[a.GetLength(0),b.GetLength(1)];for(int i=0;i<c.GetLength(0);i++)for(int j=0;j<c.GetLength(1);j++)for(int k=0;k<a.GetLength(1);k++)c[i,j]+=a[i,k]*b[k,j];Finite(c);return c;}
        public static Complex[] MatrixVector(Complex[,] a,Complex[] v){if(a.GetLength(1)!=v.Length)throw new ArgumentException("Matrix/vector dimensions do not match.");Complex[] r=new Complex[a.GetLength(0)];for(int i=0;i<r.Length;i++)for(int j=0;j<v.Length;j++)r[i]+=a[i,j]*v[j];Finite(r);return r;}
        public static Complex[,] Tensor(Complex[,] a,Complex[,] b){int n=a.GetLength(0)*b.GetLength(0),m=a.GetLength(1)*b.GetLength(1);if(n>16||m>16)throw new ArgumentException("Tensor output supports <=16x16.");Complex[,] r=new Complex[n,m];for(int i=0;i<a.GetLength(0);i++)for(int j=0;j<a.GetLength(1);j++)for(int k=0;k<b.GetLength(0);k++)for(int l=0;l<b.GetLength(1);l++)r[i*b.GetLength(0)+k,j*b.GetLength(1)+l]=a[i,j]*b[k,l];Finite(r);return r;}
        private static void Square(Complex[,] m){if(m.GetLength(0)!=m.GetLength(1))throw new ArgumentException("Square matrix required.");}
        private static void Finite(Complex[] a){foreach(Complex z in a)if(!Finite(z))throw new ArgumentException("Numerical result is nonfinite.");}
        private static void Finite(Complex[,] a){foreach(Complex z in a)if(!Finite(z))throw new ArgumentException("Numerical result is nonfinite.");}
        private static bool Finite(Complex c){return !Double.IsNaN(c.Real)&&!Double.IsInfinity(c.Real)&&!Double.IsNaN(c.Imaginary)&&!Double.IsInfinity(c.Imaginary);}
        public static double NormSquared(Complex[] v){double sum=0;foreach(Complex z in v)sum+=z.Real*z.Real+z.Imaginary*z.Imaginary;if(Double.IsNaN(sum)||Double.IsInfinity(sum))throw new ArgumentException("Norm is nonfinite.");return sum;}
        public static Complex[] Normalize(Complex[] v){Finite(v);double scale=0;foreach(Complex z in v)scale=Math.Max(scale,Math.Max(Math.Abs(z.Real),Math.Abs(z.Imaginary)));if(scale==0)throw new ArgumentException("Cannot normalize a zero vector.");Complex[] r=new Complex[v.Length];double sum=0;for(int i=0;i<v.Length;i++){r[i]=new Complex(v[i].Real/scale,v[i].Imaginary/scale);sum+=r[i].Real*r[i].Real+r[i].Imaginary*r[i].Imaginary;}double norm=Math.Sqrt(sum);for(int i=0;i<r.Length;i++)r[i]/=norm;return r;}
        public static void RequirePure(Complex[] v){if(Math.Abs(NormSquared(v)-1)>Tol)throw new ArgumentException("State must already be normalized; use q.math normalize explicitly.");}
        public static Complex[,] Density(Complex[] v){RequirePure(v);if(v.Length>16)throw new ArgumentException("Density output supports dimension <=16.");Complex[,] d=new Complex[v.Length,v.Length];for(int i=0;i<v.Length;i++)for(int j=0;j<v.Length;j++)d[i,j]=v[i]*Complex.Conjugate(v[j]);return d;}
        public static Complex Trace(Complex[,] a){Square(a);Complex r=0;for(int i=0;i<a.GetLength(0);i++)r+=a[i,i];return r;}
        public static double HermitianError(Complex[,] a){Square(a);double max=0;for(int i=0;i<a.GetLength(0);i++)for(int j=0;j<a.GetLength(0);j++)max=Math.Max(max,Complex.Abs(a[i,j]-Complex.Conjugate(a[j,i])));return max;}
        public static double[] HermitianEigenvalues(Complex[,] a)
        {
            Square(a);Finite(a);int n=a.GetLength(0);if(n>16||HermitianError(a)>Tol)throw new ArgumentException("Hermitian eigensolver requires a Hermitian matrix <=16x16.");
            int d=2*n;double[,] b=new double[d,d];double scale=0;foreach(Complex value in a)scale=Math.Max(scale,Math.Max(Math.Abs(value.Real),Math.Abs(value.Imaginary)));if(scale==0)return new double[n];for(int i=0;i<n;i++)for(int j=0;j<n;j++){Complex c=new Complex(a[i,j].Real/scale*.5+a[j,i].Real/scale*.5,a[i,j].Imaginary/scale*.5-a[j,i].Imaginary/scale*.5);b[i,j]=b[i+n,j+n]=c.Real;b[i+n,j]=c.Imaginary;b[i,j+n]=-c.Imaginary;}
            bool converged=false;for(int step=0;step<d*d*128;step++){int p=0,q=0;double off=0;for(int i=0;i<d;i++)for(int j=i+1;j<d;j++)if(Math.Abs(b[i,j])>off){off=Math.Abs(b[i,j]);p=i;q=j;}if(off<=1e-13){converged=true;break;}double tau=(b[q,q]-b[p,p])/(2*b[p,q]);double t=(tau>=0?1:-1)/(Math.Abs(tau)+Math.Sqrt(1+tau*tau));double c=1/Math.Sqrt(1+t*t),s=t*c,ap=b[p,p],aq=b[q,q],pq=b[p,q];b[p,p]=ap-t*pq;b[q,q]=aq+t*pq;b[p,q]=b[q,p]=0;for(int k=0;k<d;k++)if(k!=p&&k!=q){double x=b[k,p],y=b[k,q];b[k,p]=b[p,k]=c*x-s*y;b[k,q]=b[q,k]=s*x+c*y;}}
            if(!converged)throw new InvalidOperationException("Hermitian eigensolver did not converge.");double[] eig=new double[d];for(int i=0;i<d;i++)eig[i]=b[i,i];Array.Sort(eig);double[] r=new double[n];for(int i=0;i<n;i++){r[i]=(eig[2*i]*.5+eig[2*i+1]*.5)*scale;if(!QuantumMath.IsFinite(r[i]))throw new ArgumentException("Eigenvalue exceeds the finite FP64 range.");}return r;
        }
        public static Dictionary<string,object> DensityValidation(Complex[,] a){Square(a);double herm=HermitianError(a);Complex tr=Trace(a);double[] eig=herm<=Tol?HermitianEigenvalues(a):new double[0];double min=eig.Length>0?eig[0]:Double.NaN;bool valid=herm<=Tol&&Complex.Abs(tr-Complex.One)<=Tol&&min>=-Tol;return D("valid",valid,"hermitianError",herm,"trace",ComplexJson(tr),"eigenvalues",eig,"minimumEigenvalue",eig.Length>0?(object)min:null,"tolerance",Tol);}
        public static void RequireDensity(Complex[,] a){if(!(bool)DensityValidation(a)["valid"])throw new ArgumentException("Density matrix must be Hermitian, positive semidefinite, trace one.");}
        public static double Purity(Complex[,] rho){RequireDensity(rho);return Trace(MatrixMultiply(rho,rho)).Real;}
        public static double Entropy(Complex[,] rho,double logarithmBase){RequireDensity(rho);if(!QuantumMath.IsFinite(logarithmBase)||logarithmBase<=0||logarithmBase==1)throw new ArgumentException("Entropy base must be finite, positive and different from one.");double s=0;foreach(double raw in HermitianEigenvalues(rho)){double v=Math.Max(0,raw);if(v>0)s-=v*Math.Log(v)/Math.Log(logarithmBase);}return s;}
        public static Complex Overlap(Complex[] a,Complex[] b){if(a.Length!=b.Length)throw new ArgumentException("State dimensions differ.");Complex r=0;for(int i=0;i<a.Length;i++)r+=Complex.Conjugate(a[i])*b[i];return r;}
        public static double[] Bloch(Complex[] v){RequirePure(v);if(v.Length!=2)throw new ArgumentException("Bloch vector requires exactly two amplitudes.");Complex c=Complex.Conjugate(v[0])*v[1];return new double[]{2*c.Real,2*c.Imaginary,v[0].Magnitude*v[0].Magnitude-v[1].Magnitude*v[1].Magnitude};}
        public static double UnitarityError(Complex[,] a){Square(a);Complex[,] p=MatrixMultiply(Dagger(a),a);double max=0;for(int i=0;i<p.GetLength(0);i++)for(int j=0;j<p.GetLength(1);j++)max=Math.Max(max,Complex.Abs(p[i,j]-(i==j?Complex.One:Complex.Zero)));return max;}
        public static double MatrixDifference(Complex[,] a,Complex[,] b,bool upToPhase,out Complex phase){if(a.GetLength(0)!=b.GetLength(0)||a.GetLength(1)!=b.GetLength(1))throw new ArgumentException("Matrix dimensions differ.");phase=Complex.One;if(upToPhase){Complex dot=0;for(int i=0;i<a.GetLength(0);i++)for(int j=0;j<a.GetLength(1);j++)dot+=Complex.Conjugate(b[i,j])*a[i,j];if(Complex.Abs(dot)>1e-15)phase=dot/Complex.Abs(dot);}double max=0;for(int i=0;i<a.GetLength(0);i++)for(int j=0;j<a.GetLength(1);j++)max=Math.Max(max,Complex.Abs(a[i,j]-phase*b[i,j]));return max;}
        // Independent mathematical definitions, with first listed operand q0.
        public static Complex[,] GateMatrix(string name,double[] angles)
        {
            name=(name??"").ToLowerInvariant();if(name=="id"||name=="identity")name="i";if(name=="u3")name="u";if(name=="cnot")name="cx";if(name=="toffoli")name="ccx";if(name=="fredkin")name="cswap";
            int ac=-1,targets=0;foreach(Dictionary<string,object> d in TrancheRegister.SupportedGates)if((string)d["name"]==name){ac=(int)d["angleCount"];targets=(int)d["targetCount"];}if(ac<0||angles==null||angles.Length!=ac)throw new ArgumentException("Unknown gate or wrong angle count.");foreach(double d in angles)if(Double.IsNaN(d)||Double.IsInfinity(d)||Math.Abs(d)>1e12)throw new ArgumentException("Gate angles must be finite, magnitude <=1e12 radians.");
            if(targets==1)return LocalGate(name,angles);int dim=1<<targets;Complex[,] result=new Complex[dim,dim];
            if(name=="swap"||name=="ccx"||name=="cswap"){for(int x=0;x<dim;x++){int y=x;if(name=="swap")y=((x&1)<<1)|((x&2)>>1);if(name=="ccx"&&(x&3)==3)y=x^4;if(name=="cswap"&&(x&1)==1)y=(x&1)|((x&2)<<1)|((x&4)>>1);result[y,x]=1;}return result;}
            if(name=="rxx"||name=="ryy"||name=="rzz"||name=="rzx"){string p=name=="rzx"?"Z0 X1":name=="rxx"?"X0 X1":name=="ryy"?"Y0 Y1":"Z0 Z1";Complex[,] pauli=PauliMatrix(p,2);double c=Math.Cos(angles[0]/2),s=Math.Sin(angles[0]/2);for(int i=0;i<dim;i++)for(int j=0;j<dim;j++)result[i,j]=(i==j?new Complex(c,0):Complex.Zero)-Complex.ImaginaryOne*s*pauli[i,j];return result;}
            string local=name.Substring(1);double[] localAngles=angles;if(name=="cu")localAngles=new double[]{angles[0],angles[1],angles[2]};Complex[,] u=LocalGate(local,localAngles);Complex global=name=="cu"?Complex.Exp(Complex.ImaginaryOne*angles[3]):Complex.One;for(int x=0;x<4;x++){if((x&1)==0)result[x,x]=1;else for(int y=0;y<2;y++)result[1+(y<<1),x]=global*u[y,x>>1];}return result;
        }
        private static Complex[,] LocalGate(string name,double[] a)
        {
            Complex[,] m=new Complex[2,2];Complex I=Complex.ImaginaryOne;double h=1/Math.Sqrt(2),theta=a.Length>0?a[0]:0,c=Math.Cos(theta/2),s=Math.Sin(theta/2);switch(name){case "i":return Identity(2);case "x":m[0,1]=m[1,0]=1;break;case "y":m[0,1]=-I;m[1,0]=I;break;case "z":m[0,0]=1;m[1,1]=-1;break;case "h":m[0,0]=m[0,1]=m[1,0]=h;m[1,1]=-h;break;case "s":case "sdg":case "t":case "tdg":case "p":double phi=name=="s"?Math.PI/2:name=="sdg"?-Math.PI/2:name=="t"?Math.PI/4:name=="tdg"?-Math.PI/4:theta;m[0,0]=1;m[1,1]=Complex.Exp(I*phi);break;case "sx":case "sxdg":Complex ii=name=="sx"?I:-I;m[0,0]=m[1,1]=(1+ii)/2;m[0,1]=m[1,0]=(1-ii)/2;break;case "rx":m[0,0]=m[1,1]=c;m[0,1]=m[1,0]=-I*s;break;case "ry":m[0,0]=m[1,1]=c;m[0,1]=-s;m[1,0]=s;break;case "rz":m[0,0]=Complex.Exp(-I*theta/2);m[1,1]=Complex.Exp(I*theta/2);break;case "u":m[0,0]=c;m[0,1]=-Complex.Exp(I*a[2])*s;m[1,0]=Complex.Exp(I*a[1])*s;m[1,1]=Complex.Exp(I*(a[1]+a[2]))*c;break;default:throw new ArgumentException("Unknown local gate.");}return m;
        }
        public static Dictionary<int,char> ParsePauli(string s,int n){Dictionary<int,char> p=new Dictionary<int,char>();s=Unquote(s).Trim();if(s=="I"||s=="i"||s.Length==0)return p;foreach(string token in Regex.Split(s,@"\s+")){Match m=Regex.Match(token,@"^([IXYZixyz])([0-9]+)$");if(!m.Success)throw new ArgumentException("Paulis require explicit operands such as X0 Z1.");int q=Integer(m.Groups[2].Value,0,n-1);if(p.ContainsKey(q))throw new ArgumentException("Pauli repeats a qubit.");p.Add(q,Char.ToUpperInvariant(m.Groups[1].Value[0]));}return p;}
        public static Complex[,] PauliMatrix(string s,int n){if(n<1||n>4)throw new ArgumentException("Explicit Pauli matrices support 1..4 qubits.");Dictionary<int,char> p=ParsePauli(s,n);int d=1<<n;Complex[,] a=new Complex[d,d];for(int x=0;x<d;x++){int y;Complex phase;PauliAction(p,x,out y,out phase);a[y,x]=phase;}return a;}
        private static void PauliAction(Dictionary<int,char> p,int x,out int y,out Complex phase){y=x;phase=Complex.One;foreach(KeyValuePair<int,char> kv in p){bool one=(x&(1<<kv.Key))!=0;if(kv.Value=='X')y^=1<<kv.Key;else if(kv.Value=='Y'){y^=1<<kv.Key;phase*=one?-Complex.ImaginaryOne:Complex.ImaginaryOne;}else if(kv.Value=='Z'&&one)phase=-phase;}}

        public object Execute(string[] words){return Execute(words,0,null,null,null);}
        public object Execute(string[] words,int selectedQubits,Func<ulong,double[]> amplitude,Func<int,double[]> spin,string descriptorHash)
        {
            if(words==null||words.Length<2)throw new ArgumentException("Calculator command requires an action.");string ns=words[0].ToLowerInvariant(),action=words[1].ToLowerInvariant();Dictionary<string,string> fields=ParseFields(words);Stopwatch clock=Stopwatch.StartNew();Dictionary<string,object> result;
            if(ns=="q.math")result=MathCommand(action,fields);else if(ns=="q.query")result=QueryCommand(action,fields,selectedQubits,amplitude,spin,descriptorHash);else if(ns=="q.resource")result=ResourceCommand(action,fields);else if(ns=="q.model")result=ModelCommand(action,fields);else if(ns=="q.lesson")result=LessonCommand(action,fields);else throw new ArgumentException("Unknown calculator namespace.");
            result["namespace"]=ns;result["action"]=action;result["elapsedMs"]=clock.Elapsed.TotalMilliseconds;result["physicalQuantumOperations"]=0;result["proceduralFamilyGateCredit"]=0;result["measurementSeedChanged"]=false;result["complexLayout"]="[real,imaginary]";if(!result.ContainsKey("backend"))result["backend"]="bounded-classical-complex-FP64";if(!result.ContainsKey("resultKind"))result["resultKind"]="numerical";ValidateOutput(result);return result;
        }
        private Dictionary<string,object> MathCommand(string action,Dictionary<string,string> f)
        {
            if(action=="normalize"||action=="norm"||action=="probabilities"||action=="bloch"||action=="density"||action=="canonical-phase"){
                CheckFields(f,action=="canonical-phase"?"amplitudes preserve-original":"amplitudes");Complex[] v=ParseComplexVector(Required(f,"amplitudes"));if(action=="normalize"){Complex[] normalized=Normalize(v);object original=null;try{original=NormSquared(v);if((double)original==0)original=null;}catch(ArgumentException){}return D("amplitudes",VectorJson(normalized),"originalNormSquared",original,"originalNormSquaredRepresentable",original!=null);}double n=NormSquared(v);if(action=="norm")return D("normSquared",n,"norm",Math.Sqrt(n),"normalized",Math.Abs(n-1)<=Tol,"tolerance",Tol);RequirePure(v);if(action=="density")return D("rho",MatrixJson(Density(v)));if(action=="bloch")return D("bloch",Bloch(v));if(action=="probabilities"){double[] p=new double[v.Length];for(int i=0;i<p.Length;i++)p[i]=v[i].Magnitude*v[i].Magnitude;return D("probabilities",p,"sum",n);}Choice(f,"preserve-original","true");Complex phase=Complex.One;for(int i=0;i<v.Length;i++)if(Complex.Abs(v[i])>1e-15){phase=v[i]/Complex.Abs(v[i]);break;}Complex[] display=new Complex[v.Length];for(int i=0;i<v.Length;i++)display[i]=v[i]/phase;return D("displayAmplitudes",VectorJson(display),"originalAmplitudes",VectorJson(v),"removedDisplayPhase",ComplexJson(phase),"originalStatePreserved",true);
            }
            if(action=="from-bloch"){CheckFields(f,"theta phi");double theta=Real(Required(f,"theta")),phi=Real(Required(f,"phi"));if(theta<0||theta>Math.PI||Math.Abs(phi)>1e12)throw new ArgumentException("theta must be 0..pi and phi magnitude <=1e12.");Complex[] v={new Complex(Math.Cos(theta/2),0),Complex.Exp(Complex.ImaginaryOne*phi)*Math.Sin(theta/2)};return D("amplitudes",VectorJson(v),"bloch",Bloch(v));}
            if(action=="validate-bloch"){CheckFields(f,"x y z");double x=Real(Required(f,"x")),y=Real(Required(f,"y")),z=Real(Required(f,"z")),r=x*x+y*y+z*z;return D("valid",r<=1+Tol,"lengthSquared",r,"pure",Math.Abs(r-1)<=Tol,"tolerance",Tol);}
            if(action=="validate-density"||action=="purity"||action=="entropy"){CheckFields(f,action=="entropy"?"rho base":"rho");Complex[,] rho=ParseComplexMatrix(Required(f,"rho"));if(action=="validate-density")return DensityValidation(rho);if(action=="purity")return D("purity",Purity(rho));double b=Real(Optional(f,"base","2"));return D("entropy",Entropy(rho,b),"base",b,"eigenvalues",HermitianEigenvalues(rho));}
            if(action=="overlap"||action=="fidelity"){CheckFields(f,"a b convention");if(action=="fidelity")Choice(f,"convention","squared");Complex[] a=ParseComplexVector(Required(f,"a")),b=ParseComplexVector(Required(f,"b"));RequirePure(a);RequirePure(b);Complex c=Overlap(a,b);return action=="overlap"?D("overlap",ComplexJson(c)):D("fidelity",c.Magnitude*c.Magnitude,"convention","squared");}
            if(action=="trace-distance"){CheckFields(f,"rho sigma");Complex[,] a=ParseComplexMatrix(Required(f,"rho")),b=ParseComplexMatrix(Required(f,"sigma"));RequireDensity(a);RequireDensity(b);if(a.GetLength(0)!=b.GetLength(0))throw new ArgumentException("Density dimensions differ.");for(int i=0;i<a.GetLength(0);i++)for(int j=0;j<a.GetLength(0);j++)a[i,j]-=b[i,j];double d=0;foreach(double eig in HermitianEigenvalues(a))d+=Math.Abs(eig)/2;return D("traceDistance",d,"definition","one half trace norm of rho minus sigma");}
            if(action=="gate-matrix"){CheckFields(f,"gate angles");string gate=Required(f,"gate");double[] a=Angles(Optional(f,"angles","[]"));Complex[,] m=GateMatrix(gate,a);return D("gate",gate,"matrix",MatrixJson(m),"unitarityError",UnitarityError(m),"bitOrder","q0 least significant; controls first");}
            if(action=="compare-gates"){CheckFields(f,"p rz up-to-global-phase");bool up=Boolean(Optional(f,"up-to-global-phase","false"));Complex[,] a=GateMatrix("p",new double[]{Real(Required(f,"p"))}),b=GateMatrix("rz",new double[]{Real(Required(f,"rz"))});Complex phase;double error=MatrixDifference(a,b,up,out phase);return D("equivalent",error<=1e-12,"maximumElementError",error,"phaseMultiplier",ComplexJson(phase),"upToGlobalPhase",up,"controlledGateWarning","A phase on the controlled branch is observable: CP and CRZ are generally different.");}
            if(action=="unitary"){CheckFields(f,"matrix tolerance");double tolerance=Real(Optional(f,"tolerance","1e-12"));if(tolerance<=0||tolerance>1e-3)throw new ArgumentException("tolerance must be in (0,1e-3].");double err=UnitarityError(ParseComplexMatrix(Required(f,"matrix")));return D("unitary",err<=tolerance,"maximumElementError",err,"tolerance",tolerance);}
            if(action=="tensor"||action=="commutator"){CheckFields(f,action=="tensor"?"left right":"a b");Complex[,] a=ParseComplexMatrix(Required(f,action=="tensor"?"left":"a")),b=ParseComplexMatrix(Required(f,action=="tensor"?"right":"b"));if(action=="tensor")return D("matrix",MatrixJson(Tensor(a,b)),"factorOrder","left tensor right; right factor occupies lower-order indices");Complex[,] ab=MatrixMultiply(a,b),ba=MatrixMultiply(b,a);if(ab.GetLength(0)!=ba.GetLength(0)||ab.GetLength(1)!=ba.GetLength(1))throw new ArgumentException("Commutator dimensions differ.");for(int i=0;i<ab.GetLength(0);i++)for(int j=0;j<ab.GetLength(1);j++)ab[i,j]-=ba[i,j];return D("matrix",MatrixJson(ab),"definition","AB-BA");}
            if(action=="eigen"){CheckFields(f,"operator");Complex[,] op=ParseComplexMatrix(Required(f,"operator"));double[] eig=HermitianEigenvalues(op);Dictionary<string,object> r=D("eigenvalues",eig,"method","converged real-symmetric embedding Jacobi eigensolver");if(op.GetLength(0)==2){double scale=0;foreach(Complex z in op)scale=Math.Max(scale,Math.Max(Math.Abs(z.Real),Math.Abs(z.Imaginary)));object[] vec=new object[2];for(int k=0;k<2;k++){Complex[] v;if(scale==0||Math.Abs(eig[1]/scale-eig[0]/scale)<=1e-12)v=k==0?new Complex[]{1,0}:new Complex[]{0,1};else if(Complex.Abs(op[0,1]/scale)>1e-14)v=Normalize(new Complex[]{op[0,1]/scale,eig[k]/scale-op[0,0]/scale});else v=Math.Abs(op[0,0].Real/scale-eig[k]/scale)<=1e-12?new Complex[]{1,0}:new Complex[]{0,1};vec[k]=VectorJson(v);}r["eigenvectors"]=vec;}return r;}
            if(action=="expectation"){CheckFields(f,"state operator");Complex[] v=ParseComplexVector(Required(f,"state"));RequirePure(v);Complex[,] m=ParseComplexMatrix(Required(f,"operator"));if(HermitianError(m)>Tol)throw new ArgumentException("Observable must be Hermitian.");Complex c=Overlap(v,MatrixVector(m,v));return D("expectation",c.Real,"imaginaryResidual",c.Imaginary);}
            throw new ArgumentException("Unsupported q.math action. Use the calculator catalogue.");
        }
        public static bool Boolean(string s){bool b;if(!System.Boolean.TryParse(s,out b))throw new ArgumentException("Expected true or false.");return b;}
        public static double[] Angles(string s){string[] a=SplitList(s);double[] r=new double[a.Length];for(int i=0;i<r.Length;i++)r[i]=Real(a[i]);return r;}

        private Dictionary<string,object> QueryCommand(string action,Dictionary<string,string> f,int n,Func<ulong,double[]> get,Func<int,double[]> spin,string hash)
        {
            if(n<1||n>29||get==null||spin==null)throw new InvalidOperationException("q.query requires the current completed circuit's coherent premeasurement output. Run q.circuit first.");
            long queries=0;Func<ulong,Complex> amplitude=delegate(ulong id){double[] a=get(id);queries++;if(a==null||a.Length!=2)throw new InvalidOperationException("Selected-state amplitude callback returned invalid layout.");return new Complex(a[0],a[1]);};
            Func<int,double[]> spinQuery=delegate(int q){double[] s=spin(q);queries++;if(s==null||s.Length!=3)throw new InvalidOperationException("Selected-state spin callback returned invalid layout.");return s;};
            Dictionary<string,object> result;Complex[] full=null;Func<Complex[]> load=delegate(){if(n>MaximumFullQueryQubits)throw new InvalidOperationException("This exact joint analysis is bounded to 16 qubits/65536 calculated amplitudes. Single-qubit reductions and bounded prefix dumps support 29.");if(full==null){full=new Complex[1<<n];for(int i=0;i<full.Length;i++)full[i]=amplitude((ulong)i);RequirePure(full);}return full;};
            if(action=="amplitudes"||action=="probabilities"){CheckFields(f,"max start");int max=Integer(Optional(f,"max","16"),1,MaximumOutputRows);ulong length=1UL<<n,start=(ulong)Big(Optional(f,"start","0"),false);if(start>=length)throw new ArgumentException("start is outside selected register.");int take=(int)Math.Min((ulong)max,length-start);object[] rows=new object[take];double mass=0;for(int i=0;i<take;i++){ulong id=start+(ulong)i;Complex a=amplitude(id);double p=a.Magnitude*a.Magnitude;mass+=p;Dictionary<string,object> row=D("basisIndex",id.ToString(Inv),"bitstring",Bits(id,n),"probability",p);if(action=="amplitudes"){row["amplitude"]=ComplexJson(a);row["phaseRadians"]=p==0?(object)null:Math.Atan2(a.Imaginary,a.Real);}rows[i]=row;}result=D("rows",rows,"totalStates",length.ToString(Inv),"returnedStates",take,"start",start.ToString(Inv),"complete",start==0&&(ulong)take==length,"omittedStates",(length-(ulong)take).ToString(Inv),"returnedProbabilityMass",mass,"renormalized",false);}
            else if(action=="expectation"){CheckFields(f,"pauli");Dictionary<int,char> p=ParsePauli(Required(f,"pauli"),n);Complex e=Expectation(load(),p);result=D("pauli",f["pauli"],"expectation",e.Real,"imaginaryResidual",e.Imaginary);}
            else if(action=="stabilizers"){CheckFields(f,"generators");string[] gens=SplitList(Required(f,"generators"));if(gens.Length<1||gens.Length>64)throw new ArgumentException("Use 1..64 stabilizer candidates.");Dictionary<int,char>[] p=new Dictionary<int,char>[gens.Length];object[] rows=new object[gens.Length];bool commutes=true,stabilized=true;Complex[] v=load();for(int i=0;i<gens.Length;i++){p[i]=ParsePauli(Unquote(gens[i]),n);Complex e=Expectation(v,p[i]);bool s=Math.Abs(e.Real-1)<=Tol&&Math.Abs(e.Imaginary)<=Tol;stabilized&=s;rows[i]=D("generator",Unquote(gens[i]),"expectation",e.Real,"stabilizes",s);for(int j=0;j<i;j++)commutes&=PaulisCommute(p[i],p[j]);}result=D("rows",rows,"mutuallyCommuting",commutes,"allStabilize",stabilized,"validStabilizers",commutes&&stabilized,"scope","Candidate checks on selected pure output; this is not a phase-aware tableau backend.");}
            else if(action=="fidelity"){CheckFields(f,"state convention");Choice(f,"convention","squared");Complex[] target=ParseComplexVector(Required(f,"state"));RequirePure(target);Complex[] v=load();Complex c=Overlap(v,target);result=D("fidelity",c.Magnitude*c.Magnitude,"convention","squared");}
            else if(action=="concurrence"){CheckFields(f,"qubits");int[] q=Qubits(Required(f,"qubits"),n,2);if(n!=2||q.Length!=2)throw new InvalidOperationException("This concurrence calculator requires the entire selected pure two-qubit register. Mixed reduced concurrence needs an additional backend.");Complex[] v=load();double c=2*Complex.Abs(v[0]*v[3]-v[1]*v[2]);result=D("concurrence",c,"scope","pure two-qubit state");}
            else if(action=="negativity"){CheckFields(f,"partition convention");Choice(f,"convention","trace-norm-minus-one-divided-by-two");int[] q=Qubits(Required(f,"partition"),n,4);if(q.Length==n)throw new ArgumentException("Partition must leave a nonempty complement.");Complex[,] rho=q.Length==1?DensityFromSpin(spinQuery(q[0])):Reduced(load(),n,q);double sum=0;foreach(double eig in HermitianEigenvalues(rho))sum+=Math.Sqrt(Math.Max(0,eig));result=D("negativity",Math.Max(0,(sum*sum-1)/2),"partition",q,"convention","(trace norm of partial transpose minus one)/2","method","Schmidt spectrum identity for the globally pure selected output");}
            else if(action=="marginal"||action=="reduced-density"||action=="purity"||action=="entropy"){CheckFields(f,action=="marginal"?"qubits basis":action=="entropy"?"qubits base":"qubits");int[] q=Qubits(Required(f,"qubits"),n,4);double[] localSpin=q.Length==1?spinQuery(q[0]):null;Complex[,] rho=localSpin!=null?DensityFromSpin(localSpin):Reduced(load(),n,q);if(action=="reduced-density"){result=D("rho",MatrixJson(rho),"qubits",q,"dimension",rho.GetLength(0));if(localSpin!=null)foreach(KeyValuePair<string,object> field in BlochStateMetadata(localSpin,q[0]))result[field.Key]=field.Value;}else if(action=="purity")result=D("purity",Purity(rho),"qubits",q);else if(action=="entropy"){double b=Real(Optional(f,"base","2"));result=D("entropy",Entropy(rho,b),"base",b,"qubits",q);}else{string basis=Optional(f,"basis","z").ToLowerInvariant();if(basis!="x"&&basis!="y"&&basis!="z")throw new ArgumentException("basis must be x, y, or z.");Complex[,] local=basis=="x"?GateMatrix("h",new double[0]):basis=="y"?MatrixMultiply(GateMatrix("h",new double[0]),GateMatrix("sdg",new double[0])):Identity(2);Complex[,] rotation=Identity(1);for(int i=0;i<q.Length;i++)rotation=Tensor(local,rotation);rho=MatrixMultiply(MatrixMultiply(rotation,rho),Dagger(rotation));double[] probs=new double[1<<q.Length];for(int i=0;i<probs.Length;i++)probs[i]=Math.Max(0,rho[i,i].Real);result=D("probabilities",probs,"qubits",q,"basis",basis,"localBitOrder","First listed qubit is least significant in each local outcome.");}}
            else throw new ArgumentException("Unsupported q.query action.");
            result["descriptorHash"]=hash;result["selectedQubits"]=n;result["actualStateQueries"]=queries;result["backend"]="selected-coherent-register / classical-FP64 analysis";result["resultKind"]="analysis";result["tolerance"]=Tol;return result;
        }
        public static string Bits(ulong id,int n){char[] c=new char[n];for(int i=0;i<n;i++)c[n-1-i]=(id&(1UL<<i))!=0?'1':'0';return new string(c);}
        public static int[] Qubits(string list,int n,int max){string[] s=SplitList(list);if(s.Length<1||s.Length>max)throw new ArgumentException("Qubit list must contain 1.."+max+" distinct operands.");int[] q=new int[s.Length];HashSet<int> seen=new HashSet<int>();for(int i=0;i<q.Length;i++){q[i]=Integer(s[i],0,n-1);if(!seen.Add(q[i]))throw new ArgumentException("Repeated qubit operand.");}return q;}
        private static Complex[,] DensityFromSpin(double[] s){double len=s[0]*s[0]+s[1]*s[1]+s[2]*s[2];if(len>1+Tol)throw new InvalidOperationException("Selected-state spin lies outside Bloch ball.");return new Complex[,]{{new Complex((1+s[2])/2,0),new Complex(s[0],-s[1])/2},{new Complex(s[0],s[1])/2,new Complex((1-s[2])/2,0)}};}
        public static Dictionary<string,object> BlochStateMetadata(double[] spin,int qubit)
        {
            if(spin==null||spin.Length!=3)throw new InvalidDataException("Single-qubit Bloch data requires three components.");double lengthSquared=0;bool exactZero=true;foreach(double value in spin){if(!QuantumMath.IsFinite(value))throw new InvalidDataException("Single-qubit Bloch data is nonfinite.");lengthSquared+=value*value;exactZero&=value==0;}
            if(lengthSquared>1+Tol)throw new InvalidDataException("Single-qubit Bloch data lies outside the Bloch ball.");double purity=(1+lengthSquared)/2;bool pure=Math.Abs(lengthSquared-1)<=Tol,directionResolved=Math.Sqrt(lengthSquared)>Tol;
            return D("qubit",qubit,"bloch",(double[])spin.Clone(),"blochLengthSquared",lengthSquared,"purity",purity,"pure",pure,"mixed",!pure,"exactlyZeroBloch",exactZero,"directionDefined",!exactZero,"directionResolvedAtTolerance",directionResolved,"directionTolerance",Tol,"stateCharacter",pure?"pure-single-qubit":exactZero?"maximally-mixed-single-qubit":directionResolved?"mixed-single-qubit":"near-maximally-mixed-single-qubit","premeasurement",true,"stateSource","Selected coherent circuit premeasurement output; reduced single-qubit state.","spinScope","X/Y/Z are reduced Pauli expectations from the actual retained coherent register, not the separately saved procedural model or a postmeasurement shot. Entanglement can give a mixed local state. An exact zero vector has no preferred direction; a nonzero vector below tolerance retains its components and is labelled near-maximally mixed.");
        }
        public static Complex[,] Reduced(Complex[] state,int n,int[] keep){if(n<1||n>16||state==null||state.Length!=(1<<n)||keep==null||keep.Length<1||keep.Length>Math.Min(n,4))throw new ArgumentException("Reduced density supports 1..16 input qubits and 1..4 retained.");HashSet<int> included=new HashSet<int>();foreach(int q in keep)if(q<0||q>=n||!included.Add(q))throw new ArgumentException("Reduced density operands must be distinct in-range qubits.");int d=1<<keep.Length;Complex[,] rho=new Complex[d,d];int[] env=new int[n-keep.Length];int e=0;for(int q=0;q<n;q++)if(!included.Contains(q))env[e++]=q;int[] indices=new int[d];for(int x=0;x<(1<<env.Length);x++){int baseId=0;for(int k=0;k<env.Length;k++)if((x&(1<<k))!=0)baseId|=1<<env[k];for(int a=0;a<d;a++){int id=baseId;for(int k=0;k<keep.Length;k++)if((a&(1<<k))!=0)id|=1<<keep[k];indices[a]=id;}for(int a=0;a<d;a++)for(int b=0;b<d;b++)rho[a,b]+=state[indices[a]]*Complex.Conjugate(state[indices[b]]);}return rho;}
        private static Complex Expectation(Complex[] v,Dictionary<int,char> p){Complex e=0;for(int x=0;x<v.Length;x++){int y;Complex phase;PauliAction(p,x,out y,out phase);e+=Complex.Conjugate(v[y])*phase*v[x];}return e;}
        public static bool PaulisCommute(Dictionary<int,char> a,Dictionary<int,char> b){int anti=0;foreach(KeyValuePair<int,char> kv in a){char c;if(b.TryGetValue(kv.Key,out c)&&c!='I'&&kv.Value!='I'&&c!=kv.Value)anti++;}return anti%2==0;}

        private static BigInteger Memory(int n,string representation){if(n<0||n>1024)throw new ArgumentException("Memory estimate n must be in 0..1024.");if(representation=="statevector")return new BigInteger(16)<<(n);if(representation=="density-matrix"||representation=="unitary")return new BigInteger(16)<<(2*n);throw new ArgumentException("representation must be statevector, density-matrix, or unitary.");}
        private static Dictionary<string,object> MemoryFields(BigInteger bytes){return D("bytes",bytes.ToString(Inv),"MiB",((double)bytes/1048576).ToString("G10",Inv),"GiB",((double)bytes/1073741824).ToString("G10",Inv));}
        private Dictionary<string,object> ResourceCommand(string action,Dictionary<string,string> f)
        {
            Dictionary<string,object> r;
            if(action=="memory"){CheckFields(f,"n representation dtype units");Choice(f,"dtype","complex128");Choice(f,"units","binary");int n=Integer(Required(f,"n"),0,1024);string rep=Required(f,"representation").ToLowerInvariant();BigInteger bytes=Memory(n,rep);r=MemoryFields(bytes);r["n"]=n;r["representation"]=rep;r["complexBytes"]=16;r["transactionalStatevectorPeakBytes"]=rep=="statevector"?(2*bytes).ToString(Inv):null;r["cachedCircuitPlusTransactionalShotBytes"]=rep=="statevector"?(3*bytes).ToString(Inv):null;r["scope"]="Raw dense payload; container/allocator/OS overhead excluded. No allocation performed.";}
            else if(action=="max-n"){CheckFields(f,"memory-mib representation dtype overhead-mib");Choice(f,"dtype","complex128");double mib=Real(Required(f,"memory-mib")),overhead=Real(Optional(f,"overhead-mib","0"));if(mib<=0||overhead<0||mib>1e18||overhead>mib)throw new ArgumentException("Invalid memory/overhead budget.");BigInteger bytes=new BigInteger((mib-overhead)*1048576);string rep=Required(f,"representation").ToLowerInvariant();int n=-1;while(n<1024&&Memory(n+1,rep)<=bytes)n++;r=D("maximumRawQubits",n,"availablePayloadBytes",bytes.ToString(Inv),"representation",rep,"assumption","Raw payload only, using explicitly supplied overhead; this is not safe automatic allocation.");}
            else if(action=="factor-memory"){CheckFields(f,"block-sizes dtype");Choice(f,"dtype","complex128");string[] blocks=SplitList(Required(f,"block-sizes"));if(blocks.Length<1||blocks.Length>1024)throw new ArgumentException("Use 1..1024 factor blocks.");BigInteger total=0;int n=0;int[] sizes=new int[blocks.Length];for(int i=0;i<blocks.Length;i++){sizes[i]=Integer(blocks[i],1,1024);n=checked(n+sizes[i]);total+=Memory(sizes[i],"statevector");}r=MemoryFields(total);r["blockSizes"]=sizes;r["totalQubits"]=n;r["assumption"]="Exact independent tensor factors. Connecting entangling gates may merge factors and increase memory exponentially; sparse/container overhead excluded.";}
            else if(action=="tranche-plan"){CheckFields(f,"addresses width semantics");Choice(f,"semantics","independent-groups");BigInteger addresses=Big(Required(f,"addresses"),true);int width=Integer(Required(f,"width"),1,29);BigInteger groups=(addresses+width-1)/width;int last=(int)(addresses%width);if(last==0)last=width;r=D("addresses",addresses.ToString(Inv),"width",width,"tranches",groups.ToString(Inv),"lastTrancheQubits",last,"scope","Address-group plan only; no tranches allocated or gates executed.");}
            else if(action=="sampling"){CheckFields(f,"probability shots metric");Choice(f,"metric","standard-error");double p=Real(Required(f,"probability")),shots=Real(Required(f,"shots"));if(p<0||p>1||shots<1||shots!=Math.Floor(shots)||shots>1e15)throw new ArgumentException("Invalid Bernoulli probability or shot count.");r=D("standardError",Math.Sqrt(p*(1-p)/shots),"shots",shots,"probability",p,"assumption","Independent Bernoulli samples; standard error is not a deterministic error guarantee.");}
