            if(action=="evolve"){CheckFields(f,"n initial hamiltonian time hbar");int n=Integer(Required(f,"n"),1,1);Complex[] v=ParseComplexVector(Required(f,"initial"));RequirePure(v);if(v.Length!=2)throw new ArgumentException("Evolution supports one qubit.");Complex[,] h=Hamiltonian(Required(f,"hamiltonian"),n);double time=Real(Required(f,"time")),hbar=Real(Optional(f,"hbar","1"));if(hbar<=0)throw new ArgumentException("hbar must be positive.");double h0=(h[0,0].Real+h[1,1].Real)/2,z=(h[0,0].Real-h[1,1].Real)/2,x=h[0,1].Real,y=-h[0,1].Imaginary,r=Math.Sqrt(x*x+y*y+z*z),angle=r*time/hbar;if(Double.IsNaN(angle)||Double.IsInfinity(angle)||Math.Abs(angle)>1e12)throw new ArgumentException("Evolution phase is nonfinite or exceeds 1e12 radians.");double globalAngle=h0*time/hbar;if(!QuantumMath.IsFinite(globalAngle)||Math.Abs(globalAngle)>1e12)throw new ArgumentException("Evolution global phase is nonfinite or exceeds 1e12 radians.");Complex phase=Complex.FromPolarCoordinates(1,-globalAngle);Complex[,] u=Identity(2);double c=Math.Cos(angle),scale=r==0?0:Math.Sin(angle)/r;for(int i=0;i<2;i++)for(int j=0;j<2;j++)u[i,j]=phase*((i==j?new Complex(c,0):Complex.Zero)-Complex.ImaginaryOne*scale*(h[i,j]-(i==j?new Complex(h0,0):Complex.Zero)));Complex[] output=MatrixVector(u,v);return D("amplitudes",VectorJson(output),"unitary",MatrixJson(u),"bloch",Bloch(output),"time",time,"hbar",hbar,"equation","exp(-i H t / hbar) applied to a one-qubit state");}
            if(action=="ising"){CheckFields(f,"h J energy spins");Choice(f,"energy","sum_i h_i s_i + sum_i<j J_ij s_i s_j");Choice(f,"spins","plus-minus-one");Complex[] hc=ParseComplexVector(Required(f,"h"));if(hc.Length>12)throw new ArgumentException("Ising enumeration supports <=12 spins.");Complex[,] jc=ParseComplexMatrix(Required(f,"J"));int n=hc.Length;if(jc.GetLength(0)!=n||jc.GetLength(1)!=n)throw new ArgumentException("J must match h dimensions.");double[] h=new double[n];for(int i=0;i<n;i++){if(Math.Abs(hc[i].Imaginary)>1e-12)throw new ArgumentException("h must be real.");h[i]=hc[i].Real;}for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(Math.Abs(jc[i,j].Imaginary)>1e-12||Math.Abs(jc[i,j].Real-jc[j,i].Real)>1e-12||(i==j&&Complex.Abs(jc[i,j])>1e-12))throw new ArgumentException("J must be real symmetric with zero diagonal.");object[] rows=new object[1<<n];double min=Double.PositiveInfinity;List<string> ground=new List<string>();for(int id=0;id<rows.Length;id++){int[] spins=new int[n];for(int q=0;q<n;q++)spins[q]=(id&(1<<q))==0?1:-1;double energy=0;for(int i=0;i<n;i++){energy+=h[i]*spins[i];for(int j=i+1;j<n;j++)energy+=jc[i,j].Real*spins[i]*spins[j];}if(energy<min-1e-12){min=energy;ground.Clear();}if(Math.Abs(energy-min)<=1e-12)ground.Add(Bits((ulong)id,n));rows[id]=D("bitstring",Bits((ulong)id,n),"spins",spins,"energy",energy);}return D("rows",rows,"minimumEnergy",min,"groundBitstrings",ground.ToArray(),"convention","bit 0 means spin +1, bit 1 means spin -1; each i<j interaction counted once");}
            if(action=="qubo-to-ising"){CheckFields(f,"Q objective mapping");Choice(f,"objective","x_transpose_Q_x");Choice(f,"mapping","x=(1-s)/2");Complex[,] q=ParseComplexMatrix(Required(f,"Q"));Square(q);int n=q.GetLength(0);double constant=0;double[] h=new double[n];Complex[,] j=new Complex[n,n];foreach(Complex c in q)if(Math.Abs(c.Imaginary)>1e-12)throw new ArgumentException("Q must be real.");for(int i=0;i<n;i++){constant+=q[i,i].Real/2;h[i]-=q[i,i].Real/2;for(int k=i+1;k<n;k++){double term=(q[i,k].Real+q[k,i].Real)/4;constant+=term;h[i]-=term;h[k]-=term;j[i,k]=j[k,i]=term;}}return D("constant",constant,"h",h,"J",MatrixJson(j),"mapping","x=(1-s)/2","objective","x transpose Q x; asymmetric off-diagonal entries combined");}
            if(action=="mbqc"){CheckFields(f,"initial resource entangler measurement branch");Choice(f,"resource","one plus ancilla");Choice(f,"entangler","CZ");Choice(f,"measurement","X on input");Choice(f,"branch","all");Complex[] input=ParseComplexVector(Required(f,"initial"));RequirePure(input);if(input.Length!=2)throw new ArgumentException("One-bit teleportation requires one input qubit.");Complex[] hv=MatrixVector(GateMatrix("h",new double[0]),input),xh=MatrixVector(GateMatrix("x",new double[0]),hv);return D("branches",new object[]{D("outcome",0,"probability",.5,"uncorrectedOutput",VectorJson(hv),"correction","I","correctedOutput",VectorJson(hv)),D("outcome",1,"probability",.5,"uncorrectedOutput",VectorJson(xh),"correction","X","correctedOutput",VectorJson(hv))},"equation","CZ on input tensor plus, X-basis input measurement: output X^m H|psi>","scope","Exact analytic branch calculation; probabilities are not sampled measurement counts.");}
