        private static Complex[,] Hamiltonian(string text,int n){if(text.Length>2048)throw new ArgumentException("Hamiltonian text exceeds bound.");Complex[,] h=new Complex[1<<n,1<<n];string[] terms=Regex.Split(text.Trim(),@"\s+(?=[+-])|(?<=[0-9A-Za-z)])(?=[+-](?![0-9]+\s*\*))"); // Explicit coefficient * Pauli terms separated by semicolons is also accepted.
            if(text.IndexOf(';')>=0)terms=text.Split(';');if(terms.Length>64)throw new ArgumentException("Use <=64 explicit Pauli terms.");foreach(string raw in terms){string term=raw.Trim();int star=term.IndexOf('*');if(star<1)throw new ArgumentException("Hamiltonian terms use real-coefficient*Pauli operands, separated by semicolons (e.g. 0.5*Z0;0.2*X0).");double c=Real(term.Substring(0,star));Complex[,] p=PauliMatrix(term.Substring(star+1).Trim(),n);for(int i=0;i<h.GetLength(0);i++)for(int j=0;j<h.GetLength(1);j++)h[i,j]+=c*p[i,j];}Finite(h);return h;}
        private static void RequireList(Dictionary<string,string> f,string key,string[] supported){string[] items=SplitList(Required(f,key));HashSet<string> expected=new HashSet<string>(supported,StringComparer.OrdinalIgnoreCase);HashSet<string> got=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string item in items)if(!expected.Contains(Unquote(item))||!got.Add(Unquote(item)))throw new ArgumentException("Unsupported or duplicate "+key+" item.");if(got.Count!=expected.Count)throw new ArgumentException("This theory entry requires the documented complete "+key+" list.");}
        private static Dictionary<string,object> Theory(string explanation,params string[] references){return D("resultKind","theory","backend","documented-theory","explanation",explanation,"references",references,"executedQuantumGates",0,"executedMeasurements",0);}
        private Dictionary<string,object> LessonCommand(string action,Dictionary<string,string> f)
        {
            if(action=="amplitude-vs-probability"){CheckFields(f,"example");Complex[] a=ParseComplexVector(Required(f,"example"));RequirePure(a);double[] p=new double[a.Length];for(int i=0;i<a.Length;i++)p[i]=a[i].Magnitude*a[i].Magnitude;Dictionary<string,object> r=Theory("Complex amplitudes include phase; measurement probabilities are their squared magnitudes. Equal probabilities can hide different interference outcomes.","https://quantum.cloud.ibm.com/learning/en/courses/basics-of-quantum-information/single-systems/quantum-information");r["amplitudes"]=VectorJson(a);r["probabilities"]=p;return r;}
            if(action=="entanglement"){CheckFields(f,"compare");RequireList(f,"compare",new string[]{"plus tensor plus","Bell phi plus"});Dictionary<string,object> r=Theory("Plus tensor plus is separable although it has four nonzero computational amplitudes. Bell phi plus is entangled; its one-qubit reduced state is I/2. Superposition alone does not imply entanglement.","https://quantum.cloud.ibm.com/learning/en/courses/basics-of-quantum-information/multiple-systems/quantum-information");r["productReducedPurity"]=1;r["bellReducedPurity"]=.5;r["bellReducedEntropyBits"]=1;return r;}
            if(action=="complexity"){CheckFields(f,"classes distinguish");RequireList(f,"classes",new string[]{"P","BPP","BQP","PSPACE","NP"});RequireList(f,"distinguish",new string[]{"proven","conjectured"});Dictionary<string,object> r=Theory("Known containments include P subset BPP subset BQP subset PP subset PSPACE, and NP subset PSPACE. Strictness of these containments is not established. NP subset BQP is not known; quantum computing is not a general proof that NP-complete problems are easy.","https://arxiv.org/abs/quant-ph/9701001");r["openQuestions"]=new string[]{"NP subset BQP?","BPP equals BQP?","P equals NP?"};return r;}
            if(action=="parallelism"){CheckFields(f,"example");Choice(f,"example","grover");return Theory("A superposition does not expose all amplitudes in one measurement. Grover gives a quadratic unstructured-search query advantage, with an explicit oracle and repeated coherent iterations; state preparation, oracle cost, and classical readout remain separate costs.","https://arxiv.org/abs/quant-ph/9701001");}
            if(action=="stabilizer"){CheckFields(f,"assumptions");RequireList(f,"assumptions",new string[]{"stabilizer-input","clifford-gates","pauli-measurements"});return Theory("Stabilizer inputs, Clifford gates and Pauli measurements admit efficient phase-aware stabilizer simulation. This theorem does not apply to arbitrary nonstabilizer inputs or arbitrary non-Clifford gates; this terminal's factorized statevector backend is distinct from a tableau backend.","https://arxiv.org/abs/quant-ph/0406196");}
            if(action=="magic"){CheckFields(f,"caveats");RequireList(f,"caveats",new string[]{"input-dependent-T","qubit-Wigner-convention","nonclifford-not-sufficient-for-advantage"});Dictionary<string,object> r=Theory("T leaves |0> unchanged. Applied to |+>, it produces a nonstabilizer pure qubit with Bloch vector (1/sqrt(2),1/sqrt(2),0). Non-Clifford structure alone does not prove computational advantage. Gross's nonnegative-Wigner theorem uses odd-dimensional systems; transferring it directly to an unspecified qubit convention is invalid.","https://arxiv.org/abs/quant-ph/0403025","https://arxiv.org/abs/quant-ph/0602001");r["TOnPlusBloch"]=new double[]{1/Math.Sqrt(2),1/Math.Sqrt(2),0};return r;}
            if(action=="algorithms"){CheckFields(f,"compare scope");RequireList(f,"compare",new string[]{"shor","grover"});Choice(f,"scope","toy-calculator");return Theory("Shor's order-finding algorithm uses coherent modular arithmetic and phase estimation; a classical factor command alone is not its quantum circuit. Grover's unstructured search uses O(sqrt(N/M)) oracle queries. Toy simulations must disclose register, oracle, and classical postprocessing costs.","https://arxiv.org/abs/quant-ph/9508027","https://arxiv.org/abs/quant-ph/9605043");}
            if(action=="pqc"){CheckFields(f,"standards mode");RequireList(f,"standards",new string[]{"FIPS203","FIPS204","FIPS205"});Choice(f,"mode","verify-current-primary-sources");Dictionary<string,object> r=Theory("Primary NIST pages were checked on 2026-10-09: FIPS 203 standardizes ML-KEM key establishment, FIPS 204 ML-DSA signatures, and FIPS 205 SLH-DSA signatures. These are classical post-quantum cryptography standards, not quantum gate algorithms. This installed snapshot does not fetch later updates during calculation; use the linked primary pages for their current notices and errata.","https://csrc.nist.gov/pubs/fips/203/final","https://csrc.nist.gov/pubs/fips/204/final","https://csrc.nist.gov/pubs/fips/205/final");r["primarySourcesCheckedDate"]="2026-10-09";r["liveNetworkLookupPerformed"]=false;return r;}
            throw new ArgumentException("Unsupported q.lesson action.");
        }
